create table if not exists public.launch_readiness_audit_runs(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),actor_id uuid not null references auth.users(id),score integer not null check(score between 0 and 100),state text not null check(state in('ready','needs_attention','blocked')),summary jsonb not null default'{}',created_at timestamptz not null default now());
create index if not exists launch_readiness_audit_runs_scope_idx on public.launch_readiness_audit_runs(organization_id,workspace_id,created_at desc);
alter table public.launch_readiness_audit_runs enable row level security;
revoke all on public.launch_readiness_audit_runs from anon,authenticated;
create policy launch_readiness_audit_runs_select on public.launch_readiness_audit_runs for select to authenticated using(public.current_workspace_role(workspace_id)in('organization_owner','organization_admin'));
create or replace function public.record_launch_readiness_audit(p_workspace_id uuid,p_summary jsonb)returns void language plpgsql security definer set search_path=public as $$declare v_org uuid;v_role text;v_score integer;v_state text;begin select organization_id,public.current_workspace_role(id)into v_org,v_role from workspaces where id=p_workspace_id;if v_org is null or v_role not in('organization_owner','organization_admin')then raise exception'administrator access required';end if;v_score:=(p_summary->>'score')::integer;v_state:=p_summary->>'state';if v_score not between 0 and 100 or v_state not in('ready','needs_attention','blocked')then raise exception'invalid readiness summary';end if;insert into launch_readiness_audit_runs(organization_id,workspace_id,actor_id,score,state,summary)values(v_org,p_workspace_id,auth.uid(),v_score,v_state,jsonb_build_object('checks',coalesce(p_summary->'checks','[]'::jsonb),'debt',coalesce(p_summary->'debt','[]'::jsonb)));end$$;
revoke all on function public.record_launch_readiness_audit(uuid,jsonb)from public;
grant execute on function public.record_launch_readiness_audit(uuid,jsonb)to authenticated;
